"use client";

import { useState, useTransition } from "react";
import { Sparkles } from "lucide-react";
import { Badge, Button } from "@/components/ui";
import { generateSummaryAction } from "@/server/actions/reviews";

/** Done / undone / time summary for a period, generated by AI when configured, otherwise by rules. */
export function SummaryCard({
  periodType,
  date,
  initial,
  initialSource,
  aiEnabled,
}: {
  periodType: string;
  date: string;
  initial: string;
  initialSource: string;
  aiEnabled: boolean;
}) {
  const [text, setText] = useState(initial);
  const [source, setSource] = useState(initialSource);
  const [note, setNote] = useState<string | null>(null);
  const [pending, start] = useTransition();
  return (
    <div>
      {text ? (
        <div className="space-y-2 text-sm leading-relaxed whitespace-pre-line">{text}</div>
      ) : (
        <p className="text-sm text-muted">No summary yet. Generate one from your tasks, time and notes for this period.</p>
      )}
      <div className="mt-3 flex flex-wrap items-center gap-2">
        <Button
          size="sm"
          variant={text ? "secondary" : "primary"}
          disabled={pending}
          onClick={() =>
            start(async () => {
              setNote(null);
              const r = await generateSummaryAction(periodType, date);
              if (r.ok && r.data) {
                setText(r.data.text);
                setSource(r.data.source);
                if (r.message) setNote(r.message);
              } else if (!r.ok) setNote(r.error);
            })
          }
        >
          <Sparkles size={14} /> {pending ? "Summarising…" : text ? "Regenerate" : "Summarise"}
        </Button>
        {text ? <Badge tone={source === "ai" ? "accent" : "neutral"}>{source === "ai" ? "AI summary" : "Built-in summary"}</Badge> : null}
        {!aiEnabled ? <span className="text-xs text-muted">AI is not configured, so GoalFlow uses its built-in summary.</span> : null}
      </div>
      {note ? <p className="mt-2 text-xs text-warn">{note}</p> : null}
    </div>
  );
}
